export function initial(){return {version:3,round:0,budget:14,actions:3,done:false,started:false,tiles:['forest','pasture','crop','forest','wetland','village','pasture','crop','agro'].map((type,id)=>({...extraTileDefaults,id,type,soil:type==='pasture'?48:type==='crop'?56:80,maturity:3,wood:type==='forest'?80:type==='agro'?30:0,gather:false,timberCooldown:0,bio:false,toxic:0,cover:false,rotation:false,trail:false,bank:false,nursery:false,intensiveFish:false,fish:72,transition:0})),brigade:false,sanitation:false,cooperative:false,history:[],log:[],timberHarvest:0,conversionWood:0,totalIncome:0};}
export function neighbors(id){return Array.from({length:9},(_,i)=>i).filter(i=>Math.abs(i%3-id%3)+Math.abs(Math.floor(i/3)-Math.floor(id/3))===1);}
export const nearWater=(s,id)=>neighbors(id).some(i=>s.tiles[i].type==='wetland');
export function habitat(t){return t.type==='forest'?(.4+.6*t.maturity/3)*(0.7+.3*t.wood/80)*(t.gather?.96:1):t.type==='wetland'?.85:t.type==='agro'?.55:t.type==='silvo'?.35:t.bio?.2:.03;}
export function local(s,id){const t=s.tiles[id],ns=neighbors(id).map(i=>s.tiles[i]),refuges=ns.reduce((a,t)=>a+habitat(t),0),toxic=[t,...ns].filter(t=>t.toxic).length;return {poll:clamp(30+refuges*25+(t.bio?20:0)-toxic*24),pred:clamp(18+refuges*24+(t.bio?42:0)-toxic*15),refuges};}
export function metrics(s,event=EVENTS[Math.min(s.round,5)]){
 const wet=s.tiles.filter(t=>t.type==='wetland'),buffers=s.tiles.filter(t=>t.type==='forest'&&nearWater(s,t.id)).reduce((a,t)=>a+habitat(t),0)+wet.filter(t=>t.bank).length*.6;
 let runoff=0,soil=0,biodiv=0,carbon=0,food=0,forestFood=0,loss=0,poll=0,preds=0,crops=0;
 for(const t of s.tiles){soil+=t.soil;biodiv+=habitat(t);carbon+=t.wood*.3;if(t.type==='crop')runoff+=(t.cover?1.8:7)*(t.noTill?.85:1)*(t.cropRotation?.9:1);if(t.fertilizer)runoff+=t.cover?2:5;if(t.type==='pasture'||t.type==='silvo')runoff+=t.rotation?1.5:4;if(t.toxic)runoff+=9;}
 let water=clamp(51+wet.length*10+buffers*8+(s.sanitation?15:0)-runoff*.85-(event.kind==='drought'?10:0)-(event.kind==='storm'?runoff*.3:0));
 const irrigationCount=s.tiles.filter(t=>t.irrigation&&['crop','agro'].includes(t.type)).length,waterAvailability=clamp(77+wet.length*4+buffers*3-irrigationCount*7-(event.kind==='drought'?25:0));
 const retention=clamp(25+wet.length*20+buffers*8+soil/9*.2),biodiversity=clamp(biodiv*16);
 for(const t of s.tiles){const l=local(s,t.id);let p=0;
 if(t.type==='crop'||t.type==='agro'){crops++;poll+=l.poll;preds+=l.pred;const base=t.type==='crop'?16:14*(.45+.55*t.maturity/3);p=base*(.4+.6*t.soil/100)*(.5+.5*l.poll/100)*(t.bio?.93:1)*(t.transition?.82:1)*(t.fertilizer?1.18:1)*(t.bioGrowth?1+.12*(t.soil/100)*(t.toxic?.25:1):1)*(t.compost?1.03:1)*(fullSPD(t)?1.05:1);let risk=0;
 if(event.kind==='pests'){risk=.48*(1-l.pred/100)*(t.cropRotation?.78:1);if(t.mip&&risk>.14)risk*=.6;if(t.microbial)risk*=t.toxic?.8:.55;if(t.toxic)risk=Math.min(risk,.05);}
 if(event.kind==='drought')risk=.33*(t.cover?.5:1)*(t.type==='agro'?.6:1)*(fullSPD(t)?.8:1)*(t.irrigation?(waterAvailability>35?.45:.85):1)*(1+Math.max(0,45-waterAvailability)/100);
 if(event.kind==='storm'&&nearWater(s,t.id))risk=.35*(1-retention/140)*(t.cover?.55:1);
 if(event.kind==='fire')risk=s.brigade?.025:.12;
 loss+=p*risk;p*=1-risk;
 }else if(t.type==='pasture'||t.type==='silvo'){p=(t.type==='silvo'?7.7:7.5)*(.35+.65*t.soil/100)*(t.rotation?1.18:1)*(t.transition?.75:1);if(event.kind==='drought')p*=t.type==='silvo'?(.68+.17*t.maturity/3):t.rotation?.78:.58;if(event.kind==='fire')p*=s.brigade?.96:t.rotation?.83:.65;
 }else if(t.type==='wetland'){p=(t.nursery?3.5:t.intensiveFish?7:4.5)*(t.fish/100)*(.35+.65*water/100);}
 if(t.type==='forest'){const f=(t.gather?4:1.4)*(.35+.65*t.maturity/3);p+=f;forestFood+=f;}if(t.type==='agro'&&t.gather){p+=2;forestFood+=2;}food+=p;
 }
 const provision=clamp(food*2),support=clamp(soil/9*.5+biodiversity*.5),regulation=clamp(water*.5+retention*.25+clamp(carbon*1.45)*.25),trails=s.tiles.filter(t=>t.trail).length,cultural=clamp(18+biodiversity*.25+water*.15+trails*16),wellbeing=clamp(provision*.4+water*.35+cultural*.25-Math.max(0,40-Math.min(provision,water))*.5),livelihood=clamp(provision*.65+trails*8+(s.cooperative?14:0)+forestFood*1.8+s.log.filter(l=>l.round===s.round+1).reduce((a,l)=>a+(l.woodUsed||0),0)*.8);
 return {food:provision,regulation,support,cultural,water,soil:soil/9,biodiversity,carbon:clamp(carbon*1.45),retention,wellbeing,livelihood,foodUnits:food,forestFood,pollination:crops?poll/crops:0,predators:crops?preds/crops:0,loss,trails,woodStock:s.tiles.reduce((a,t)=>a+t.wood,0),fishStock:wet.length?wet.reduce((a,t)=>a+t.fish,0)/wet.length:0,waterAvailability};
}
export function allowed(s,id,a){a=typeof a==='string'?ACTIONS.find(x=>x.id===a):a;const t=s.tiles[id];if(!a||!t||s.done||!a.types.includes(t.type))return false;if(a.river&&!nearWater(s,id))return false;const flags={notill:'noTill',crop_rotation:'cropRotation',compost:'compost',bio_growth:'bioGrowth',microbial:'microbial',mip:'mip',fertilizer:'fertilizer',drip:'irrigation',gather:'gather',cover:'cover',biocontrol:'bio',rotation:'rotation',trail:'trail',bank:'bank',nursery:'nursery',fish:'intensiveFish'};if(flags[a.id]&&t[flags[a.id]])return false;if(a.id==='timber'&&(t.wood<18||t.timberCooldown))return false;if(a.id==='spray'&&t.toxic)return false;if(a.id==='sanitation'&&s.sanitation||a.id==='cooperative'&&s.cooperative||a.id==='brigade'&&s.brigade)return false;return true;}
function changeUse(s,t,type){if(t.wood>0){const used=t.wood*.55;s.timberHarvest+=used;s.conversionWood+=used;s.budget+=Math.floor(used/12);t.wood=0;}t.type=type;t.maturity=type==='forest'||type==='agro'||type==='silvo'?0:3;t.gather=false;t.bio=false;t.cover=false;t.rotation=false;t.trail=false;t.nursery=false;t.intensiveFish=false;Object.assign(t,extraTileDefaults);t.transition=2;}
export function apply(s,id,actionId){const a=ACTIONS.find(x=>x.id===actionId);if(!allowed(s,id,a))return {ok:false,reason:'Este manejo não está disponível neste setor.'};if(s.actions<1)return {ok:false,reason:'O trabalho previsto para este ciclo já foi utilizado.'};if(s.budget<a.cost)return {ok:false,reason:'Os recursos deste ciclo são insuficientes.'};const before=metrics(s),t=s.tiles[id],oldType=t.type,oldHarvest=s.timberHarvest;s.budget-=a.cost;s.actions--;
 if(a.id==='gather')t.gather=true;if(a.id==='timber'){t.wood-=14;t.timberCooldown=3;s.timberHarvest+=14;s.budget+=3;}
 if(a.id==='to_crop'){changeUse(s,t,'crop');t.soil=clamp(t.soil-5);}if(a.id==='to_pasture'){changeUse(s,t,'pasture');t.soil=clamp(t.soil-3);}
 if(a.id==='notill'){t.noTill=true;t.transition=Math.max(t.transition,1);}if(a.id==='crop_rotation'){t.cropRotation=true;t.transition=Math.max(t.transition,1);}if(a.id==='compost')t.compost=true;if(a.id==='bio_growth')t.bioGrowth=3;if(a.id==='microbial')t.microbial=2;if(a.id==='mip')t.mip=true;if(a.id==='fertilizer')t.fertilizer=2;if(a.id==='drip')t.irrigation=true;
 if(a.id==='cover'){t.cover=true;t.transition=Math.max(t.transition,1);}if(a.id==='biocontrol')t.bio=true;if(a.id==='spray'){t.toxic=2;}
 if(a.id==='agro')changeUse(s,t,'agro');if(a.id==='rotation'){t.rotation=true;t.transition=Math.max(t.transition,1);}if(a.id==='silvo'){changeUse(s,t,'silvo');t.rotation=true;}
 if(a.id==='restore'){const retained=t.wood;t.type='forest';t.wood=retained;t.maturity=0;t.gather=false;t.bio=false;t.cover=false;t.rotation=false;t.trail=false;Object.assign(t,extraTileDefaults);t.transition=2;}if(a.id==='rewet'){changeUse(s,t,'wetland');t.fish=45;}
 if(a.id==='fish'){t.intensiveFish=true;t.nursery=false;}if(a.id==='nursery'){t.nursery=true;t.intensiveFish=false;}if(a.id==='bank')t.bank=true;if(a.id==='trail')t.trail=true;
 if(a.id==='sanitation')s.sanitation=true;if(a.id==='cooperative')s.cooperative=true;if(a.id==='brigade')s.brigade=true;
 const record={round:s.round+1,tile:id,action:a.id,name:a.name,oldType,newType:t.type,gains:[...a.gains],losses:[...a.losses],woodUsed:s.timberHarvest-oldHarvest};s.log.push(record);return {ok:true,record,before,after:metrics(s)};}
export function advance(s){if(s.done)return null;const e=EVENTS[s.round],m=metrics(s,e),income=5+Math.floor(m.food/22)+m.trails+(s.cooperative?2:0),notes=[];
 if(e.kind==='normal')notes.push('Os alimentos, a pesca e os produtos das árvores contribuíram conforme os usos presentes no território.');
 if(e.kind==='drought')notes.push(s.tiles.some(t=>t.cover||t.rotation||t.type==='silvo')?'Cobertura do solo, descanso do pasto ou árvores amorteceram parte do efeito da seca.':'Setores sem cobertura ou descanso ficaram mais expostos à falta de água.');
 if(e.kind==='pests')notes.push(s.tiles.some(t=>t.bio)?'Os refúgios de inimigos naturais ajudaram a reduzir a herbivoria nos cultivos manejados.':'A resposta dos cultivos dependeu dos refúgios da vizinhança e do controle adotado.');
 if(e.kind==='storm')notes.push(m.water<45?'A enxurrada levou sedimentos e resíduos para a água da comunidade.':'A vegetação e o manejo do solo retiveram parte dos sedimentos antes de alcançarem a água.');
 if(e.kind==='fire')notes.push(s.brigade?'A brigada reduziu os danos do incêndio à produção.':'O incêndio causou perdas; pastos com descanso tiveram menor exposição neste cenário.');
 if(e.kind==='drought'&&s.tiles.some(t=>t.irrigation))notes.push('A irrigação reduziu parte das perdas nos setores equipados, mas retirou água do recurso compartilhado.');
 if(e.kind==='pests'&&s.tiles.some(t=>t.microbial||t.mip))notes.push('Bioinseticidas seletivos ou monitoramento integrado modificaram a resposta dos setores manejados, sem eliminar toda a herbivoria.');
 if(s.tiles.some(t=>fullSPD(t)))notes.push('Cobertura, rotação e mínimo revolvimento passaram a funcionar em conjunto no sistema de plantio direto.');
 if(s.tiles.some(t=>t.toxic))notes.push('O inseticida protegeu parte do cultivo, mas seus efeitos também alcançaram insetos não alvo e a água.');
 for(const t of s.tiles){if(['forest','agro','silvo'].includes(t.type)){t.maturity=Math.min(3,t.maturity+1);t.wood=clamp(t.wood+(t.type==='forest'?5:3));}let delta=t.type==='crop'?(-4+(t.cover?6:0)+(t.noTill?1:0)+(t.cropRotation?1:0)+(t.compost?2:0)+(t.bioGrowth&&!t.toxic?1:0)):t.type==='pasture'||t.type==='silvo'?(t.rotation?4:-3):2;if(e.kind==='fire'&&!s.brigade&&(t.type==='pasture'||t.type==='silvo'))delta-=t.rotation?2:8;t.soil=clamp(t.soil+delta);if(t.type==='wetland')t.fish=clamp(t.fish+(t.nursery?8:t.intensiveFish?-16:2)+(m.water<40?-6:0));t.toxic=Math.max(0,t.toxic-1);t.timberCooldown=Math.max(0,t.timberCooldown-1);t.bioGrowth=Math.max(0,t.bioGrowth-1);t.microbial=Math.max(0,t.microbial-1);t.fertilizer=Math.max(0,t.fertilizer-1);t.transition=Math.max(0,t.transition-1);}
 s.budget+=income;s.totalIncome+=income;s.history.push({round:s.round+1,event:e.name,...m,income,notes});s.round++;s.actions=3;s.done=s.round===6;return {event:e,notes,income};}
export function score(s){if(!s.done)return null;const m=metrics(s),avg=k=>s.history.reduce((a,h)=>a+h[k],0)/s.history.length;return Math.round(clamp(avg('food')*.25+avg('water')*.25+m.support*.2+m.cultural*.15+avg('livelihood')*.15));}
export function tileFacts(s,id){const t=s.tiles[id],facts=[];if(t.type==='forest')facts.push('Madeira em pé para usos futuros','Frutos, sementes e habitat','Solo protegido pela vegetação');if(t.type==='crop')facts.push(t.cropRotation?'Abóbora e outros cultivos em rotação':'Produção de abóbora e renda agrícola',t.cover?'Solo protegido por palhada':'Solo com períodos de exposição',t.bio?'Faixas floridas e inimigos naturais':'Polinização ligada aos refúgios vizinhos');if(t.type==='pasture'||t.type==='silvo')facts.push('Forragem e produção animal',t.rotation?'Piquetes com períodos de descanso':'Uso contínuo da forragem',t.type==='silvo'?'Árvores em implantação ou crescimento':'Pouca sombra arbórea');if(t.type==='wetland')facts.push('Pesca e reprodução de peixes',t.nursery?'Parte da captura está restringida':t.intensiveFish?'Captura ampliada neste setor':'Captura em nível inicial',t.bank?'Vegetação da margem em recuperação':'Água recebe os efeitos dos outros setores');if(t.type==='agro')facts.push('Cultivos e árvores compartilhando o setor',t.maturity<3?'Produção em fase de implantação':'Produtos em diferentes estratos',t.gather?'Colheita de frutos e sementes organizada':'Possibilidade de diversificar colheitas');if(t.type==='village')facts.push('Famílias e escola dependem da paisagem',s.sanitation?'Efluentes com tratamento':'Efluentes ainda pressionam a água',s.cooperative?'Compra e venda locais organizadas':'Acesso aos produtos pode ser organizado');if(['crop','agro'].includes(t.type)){if(fullSPD(t))facts.push('Plantio direto: cobertura, rotação e mínimo revolvimento');else{if(t.noTill)facts.push('Semeadura com mínimo revolvimento');if(t.cropRotation)facts.push('Rotação de culturas em uso');}if(t.compost)facts.push('Matéria orgânica de compostagem');if(t.bioGrowth)facts.push('Bioinsumo para crescimento em atividade');if(t.microbial)facts.push('Bioinseticida microbiano em atividade');if(t.mip)facts.push('Monitoramento integrado das pragas');if(t.fertilizer)facts.push('Nutrientes de adubação mineral disponíveis');if(t.irrigation)facts.push('Irrigação retira água compartilhada');}if(nearWater(s,id)&&t.type!=='wetland')facts.push('Este setor faz margem com a água');if(t.toxic)facts.push('Há efeito temporário de inseticida');return facts;}
export function validSave(s){return s?.version===3&&Array.isArray(s.tiles)&&s.tiles.length===9&&s.tiles.every((t,i)=>t.id===i&&TYPES[t.type]&&Number.isFinite(t.soil)&&Number.isFinite(t.wood)&&Number.isFinite(t.fish))&&Number.isInteger(s.round)&&s.round>=0&&s.round<=6&&Number.isFinite(s.budget)&&s.budget>=0&&Number.isInteger(s.actions)&&s.actions>=0&&s.actions<=3&&s.done===(s.round===6)&&Array.isArray(s.history)&&s.history.length===s.round&&Array.isArray(s.log);}

export function migrateSave(input){if(!input||![2,3].includes(input.version))return null;const s=structuredClone(input),wasV2=s.version===2;if(!Array.isArray(s.tiles))return null;for(const t of s.tiles){const oldCover=t.cover;for(const [k,v] of Object.entries(extraTileDefaults))if(t[k]===undefined)t[k]=v;if(wasV2&&oldCover)t.cropRotation=true;}if(wasV2){s.version=3;if(!s.done)s.actions=Math.min(3,s.actions+1);}return validSave(s)?s:null;}
